const fileName = $json?.name ?? 'file sconosciuto';
const binary = $binary?.data;
let content = '';

if (binary?.data) {
  content = Buffer.from(binary.data, 'base64').toString('utf-8');
}

if (!content) {
  console.warn(`[KB Update] TXT vuoto o illeggibile: ${fileName}`);
}

return { json: { fileName, content, skipped: !content, reason: content ? null : 'TXT vuoto o illeggibile' } };

const fileName = $('04 · Smista per Tipo File').item.json?.name ?? 'file sconosciuto';
const content = ($json.text || '').trim();

if (!content) {
  console.warn(`[KB Update] PDF senza testo estraibile (probabile scansione/immagine senza OCR): ${fileName}`);
}

return { json: { fileName, content, skipped: !content, reason: content ? null : 'PDF senza testo estraibile (serve OCR, non incluso in questo PoC)' } };

const fileName = $('04 · Smista per Tipo File').item.json?.name ?? 'file sconosciuto';
const content = ($json.text || '').trim();

if (!content) {
  console.warn(`[KB Update] DOCX senza testo estraibile: ${fileName}`);
}

return { json: { fileName, content, skipped: !content, reason: content ? null : 'DOCX senza testo estraibile' } };

const fileName = $json?.name ?? 'file sconosciuto';
const mimeType = $json?.mimeType ?? 'sconosciuto';

// Gestione esplicita del caso 'formato non supportato': logghiamo e saltiamo,
// non lasciamo che il workflow crashi o che il file finisca silenziosamente ignorato.
console.warn(`[KB Update] File non supportato, saltato: ${fileName} (${mimeType})`);

return { json: { fileName, content: '', skipped: true, reason: `Formato non supportato: ${mimeType}` } };

const items = $input.all();
let kbText = '';
let processedCount = 0;
let skippedFiles = [];

for (const item of items) {
  const fileName = item.json?.fileName ?? 'file sconosciuto';
  const content = item.json?.content ?? '';
  const skipped = !!item.json?.skipped;

  if (skipped || !content) {
    skippedFiles.push({ fileName, reason: item.json?.reason ?? 'contenuto vuoto' });
    continue;
  }

  kbText += `\n\n=== ${fileName} ===\n${content}`;
  processedCount++;
}

if (skippedFiles.length > 0) {
  console.warn('[KB Update] File saltati:', JSON.stringify(skippedFiles));
}

return {
  json: {
    kbContent: kbText.trim(),
    updatedAt: new Date().toISOString(),
    fileCount: items.length,
    processedCount,
    skippedCount: skippedFiles.length,
    skippedFiles
  }
};
